<?php
declare(strict_types=1);
namespace CajeerBook;

/** Escape every model-generated byte; raw Markdown appears only as plaintext. */
final class EditorAssistantView
{
    private static function e(string $value):string {return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private static function field(string $key,string $value):string {return '<input type="hidden" name="'.self::e($key).'" value="'.self::e($value).'">';}
    public static function render(array $db,string $csrf,array $actor,array $users,array $query=[],?array $result=null,string $notice=''):string {
        $url=WorkspaceUrls::url('/studio/assistant');$selected=is_string($query['page']??null)?$query['page']:'';
        $h='<div class="eyebrow">STUDIO / AI</div><h1>Editor AI Assistant</h1><p><a href="'.self::e(WorkspaceUrls::url('/studio')).'">Return to Studio</a> · <a href="'.self::e(WorkspaceUrls::url('/studio/reviews')).'">Review queue</a></p>';
        $h.='<p>Draft text, migration errors and audit findings are sent to OpenAI only when you submit a request. Remove secrets and personal information before use. Model output is untrusted; it never publishes content. Generated changes require an independent review.</p>';
        if(!EditorAssistant::enabled())$h.='<p role="alert">Editor AI is disabled. Configure <code>BOOK_EDITOR_AI_ENABLED=1</code> and <code>BOOK_CHAT_API_KEY</code> on the server.</p>';
        if($notice!=='')$h.='<p role="alert">'.self::e($notice).'</p>';
        $pages=PageTree::ordered(PageTree::drafts($db));
        $pageOptions='<option value="">Select page</option>';
        foreach($pages as $key=>$p)$pageOptions.='<option value="'.self::e($key).'"'.($selected===$key?' selected':'').'>'.self::e($p['title'].' · '.$key).'</option>';
        $scopes=[];foreach($db['pages'] as $key=>$v)$scopes[PageTree::scope($key)]=true;
        $scopeOptions='<option value="">All pages (up to 60 findings)</option>';foreach(array_keys($scopes) as $scope)$scopeOptions.='<option value="'.self::e($scope).'">'.self::e($scope).'</option>';
        $h.='<h2>Documentation coverage audit</h2><form method="post" action="'.self::e($url).'" class="editor">'.self::field('csrf',$csrf).self::field('action','gaps').'<label>Book/version<select name="scope">'.$scopeOptions.'</select></label><button>Analyze gaps</button></form>';
        $h.='<h2>Explain migration/import failure</h2><form method="post" action="'.self::e($url).'" class="editor">'.self::field('csrf',$csrf).self::field('action','migration').'<label>Error message (redact credentials, paths or tokens)<textarea name="error" maxlength="4000" rows="6" required></textarea></label><button>Explain error</button></form>';
        $h.='<h2>Propose a page correction</h2><form method="post" action="'.self::e($url).'" class="editor">'.self::field('csrf',$csrf).self::field('action','suggest').'<label>Existing page<select name="page" required>'.$pageOptions.'</select></label><label>Requested change<textarea name="instruction" maxlength="1000" rows="3" required placeholder="Fix outdated instructions using only the facts in this page"></textarea></label><button>Generate review proposal</button></form>';
        if($result===null)return $h;
        if(($result['type']??'')==='gaps'){
            $h.='<h2>Coverage findings</h2><p>'.count($result['issues']).' flagged pages (bounded scan). A flag is an editing lead, not proof that documentation is wrong.</p><ol>';
            foreach($result['issues'] as $item)$h.='<li><a href="'.self::e(WorkspaceUrls::url('/studio?edit='.rawurlencode($item['key']))).'">'.self::e($item['title']).'</a> — '.self::e(implode('; ',$item['reasons'])).'</li>';
            $h.='</ol><h3>AI prioritization</h3><pre class="history-source"><code>'.self::e($result['advice']).'</code></pre>';
        }elseif(($result['type']??'')==='migration'){
            $h.='<h2>Diagnostic explanation</h2><pre class="history-source"><code>'.self::e($result['answer']).'</code></pre><p>Verify each proposed repair against the current database state and backups. No migration commands were executed.</p>';
        }elseif(($result['type']??'')==='suggest'){
            $p=$result['proposal'];$h.='<h2>Proposed changes: '.self::e($p['key']).'</h2><p>Revision '.(int)$p['revision'].' · AI-generated Markdown, not yet saved.</p>';
            $h.='<div class="history-diff" aria-label="Proposed Markdown diff">';foreach(RevisionHistory::diff($p['body'],$p['proposal']) as [$kind,$text])$h.='<pre class="diff-'.self::e($kind).'">'.self::e(($kind==='add'?'+ ':($kind==='remove'?'- ':'  ')).$text).'</pre>';$h.='</div>';
            $h.='<details><summary>Review exact generated Markdown</summary><pre class="history-source"><code>'.self::e($p['proposal']).'</code></pre></details>';
            $options='';
            $stale=!isset($db['pages'][$p['key']])||($db['pages'][$p['key']]['revision']??null)!==$p['revision'];
            $excluded=$stale?[]:ReviewWorkflow::authors($db,$actor,'page',$p['key']);
            foreach($users as $id=>$u)if(!in_array($id,$excluded,true)&&Permissions::allows($u['role']??'none','publish'))$options.='<option value="'.self::e($id).'">'.self::e($u['username'].' · '.$u['role']).'</option>';
            if($stale)$h.='<p role="alert">The page changed during generation. Regenerate the proposal before submitting.</p>';
            elseif($options==='')$h.='<p role="alert">An independent Admin/Owner is required to submit this proposal for review. Add an eligible reviewer before applying.</p>';
            else{$h.='<form method="post" action="'.self::e($url).'" class="editor">'.self::field('csrf',$csrf).self::field('action','submit').self::field('payload',$result['sealed']['payload']).self::field('signature',$result['sealed']['signature']).'<label>Independent reviewer<select name="reviewer" required><option value="">Choose reviewer</option>'.$options.'</select></label><p>The page will be saved as a draft and submitted to review in the same transaction. This does not publish it.</p><button class="primary" data-confirm="Submit generated changes for independent review?">Save and submit to review</button></form>';}
        }
        return $h;
    }
}
